const e = (value) => String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;");
const status = (team) => ({ draft: "编组中", ready_code: "待发 Code", issued: "Workshop 中", ta_qualified: "可参赛", dissolved: "已解散" }[team.status] || team.status);
const members = (team) => `${e(team.teamNumber)} · ${team.members.map((m) => `${e(m.nickname)} · ${e(m.staffShortId)}`).join("、")}`;

export function renderLegacyStaff(root, state, api, controls) {
  if (!controls.ui.scannerOpen) stopScanner(controls.ui);
  if (!state.staffSession && !state.participants) return loginView(root, controls);
  const tab = controls.ui.tab || "overview"; const teams = state.teams || []; const qualified = teams.filter((t) => t.qualificationStatus === "ta_qualified").length;
  const content = { overview: overview(state, teams, qualified, controls.ui), grouping: grouping(state, controls.ui), codes: codeTab(state, teams), ta: taTab(state, teams, controls.ui), competition: competition(state, teams, controls.ui), audit: auditTab(state.auditLog || [], controls.ui) }[tab];
  root.innerHTML = `<div class="staff-shell"><header class="staff-top"><div><strong>⚽ 现场运营台</strong><small>${e(state.event?.name || "北京 MeetUp")}</small></div><button class="text-button" data-action="logout">退出</button></header><p class="notice" aria-live="polite"></p><main>${content}</main><nav class="bottom-tabs"><button data-tab="overview" class="${tab === "overview" ? "active" : ""}">总览</button><button data-tab="grouping" class="${tab === "grouping" ? "active" : ""}">组队</button><button data-tab="codes" class="${tab === "codes" ? "active" : ""}">Code</button><button data-tab="ta" class="${tab === "ta" ? "active" : ""}">TA</button><button data-tab="competition" class="${tab === "competition" ? "active" : ""}">比赛</button><button data-tab="audit" class="${tab === "audit" ? "active" : ""}">记录</button></nav></div>`;
  controls.ui.staffEventAbort?.abort(); const staffEventAbort = new AbortController(); controls.ui.staffEventAbort = staffEventAbort;
  const notice = root.querySelector(".notice"); const action = async (fn, ok, trigger, pendingLabel = "正在保存…") => {
    if (controls.ui.actionPending) return;
    controls.ui.actionPending = true;
    controls.ui.pendingActionLabel = pendingLabel;
    const originalLabel = trigger?.textContent;
    if (trigger) { trigger.disabled = true; trigger.setAttribute("aria-busy", "true"); trigger.textContent = pendingLabel; }
    try {
      await fn();
      await controls.refresh();
      const refreshedNotice = document.querySelector(".notice"); if (refreshedNotice) refreshedNotice.textContent = ok;
    } catch (error) {
      notice.textContent = error.message;
    } finally {
      controls.ui.actionPending = false;
      controls.ui.pendingActionLabel = "";
      if (trigger?.isConnected) { trigger.disabled = false; trigger.removeAttribute("aria-busy"); trigger.textContent = originalLabel; }
    }
  };
  root.addEventListener("click", (event) => {
    const button = event.target.closest("button"); if (!button) return;
    if (button.dataset.tab) { closeScanner(controls.ui); controls.ui.tab = button.dataset.tab; renderStaff(root, state, api, controls); return; }
    if (button.dataset.action === "logout") { closeScanner(controls.ui); return controls.logout(); }
    if (button.dataset.action === "scan") return startScanner(root, state, controls, api, notice);
    if (button.dataset.action === "stop-scan") { closeScanner(controls.ui); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "scan-again") { controls.ui.scanResultRaw = ""; controls.ui.scanResultPersonId = ""; controls.ui.peopleQuery = ""; return startScanner(root, state, controls, api, notice); }
    if (button.dataset.action === "select-scan-result") { controls.ui.selectedPersonIds = [button.dataset.personId]; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "open-scan-result-team") { controls.ui.groupingTab = "teams"; controls.ui.teamConfigId = button.dataset.teamId; controls.ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.filter) { controls.ui.taFilter = button.dataset.filter; return renderStaff(root, state, api, controls); }
    if (button.dataset.auditFilter) { controls.ui.auditFilter = button.dataset.auditFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.groupingTab) { controls.ui.groupingTab = button.dataset.groupingTab; controls.ui.selectedPersonIds = []; controls.ui.teamConfigId = null; return renderStaff(root, state, api, controls); }
    if (button.dataset.peopleFilter) { controls.ui.peopleFilter = button.dataset.peopleFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.teamPeopleFilter) { controls.ui.teamPeopleFilter = button.dataset.teamPeopleFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.teamPickerFilter) { controls.ui.teamPickerFilter = button.dataset.teamPickerFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "toggle-person") { togglePerson(controls.ui, button.dataset.personId); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "clear-people") { controls.ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "new-team") { queueAssignment(state, controls.ui, "new"); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "open-team-picker") { if (!(controls.ui.selectedPersonIds || []).length) return; controls.ui.teamPickerOpen = true; controls.ui.teamPickerQuery = ""; controls.ui.teamPickerFilter = "all"; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-team-picker") { controls.ui.teamPickerOpen = false; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "choose-team") { queueAssignment(state, controls.ui, button.dataset.teamId); controls.ui.teamPickerOpen = false; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "remove-selected") { if (!(controls.ui.selectedPersonIds || []).length) return; queueAssignment(state, controls.ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-assignment") { controls.ui.pendingAssignment = null; controls.ui.dissolutionActions = {}; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "confirm-assignment") { const pending = controls.ui.pendingAssignment; if (!pending) return; const pendingLabel = pending.targetTeamId === "new" ? "正在创建队伍…" : pending.targetTeamId ? "正在加入队伍…" : "正在移出队伍…"; return action(() => api.dispatchPeople(pending.participantIds, pending.targetTeamId, controls.ui.dissolutionActions || {}), "人员与队伍关系已更新。", button, pendingLabel).then(() => { controls.ui.selectedPersonIds = []; controls.ui.pendingAssignment = null; controls.ui.dissolutionActions = {}; controls.ui.teamConfigId = null; }); }
    if (button.dataset.action === "open-team-config") { controls.ui.teamConfigId = button.dataset.teamId; controls.ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-team-config") { controls.ui.teamConfigId = null; controls.ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-add-selected") { if (!(controls.ui.selectedPersonIds || []).length) return; queueAssignment(state, controls.ui, button.dataset.teamId); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-remove-member") { controls.ui.selectedPersonIds = [button.dataset.personId]; queueAssignment(state, controls.ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-transfer-member") { controls.ui.selectedPersonIds = [button.dataset.personId]; controls.ui.teamPickerOpen = true; controls.ui.teamPickerQuery = ""; controls.ui.teamPickerFilter = "all"; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "dissolve-team") { const team = state.teams.find((item) => item.id === button.dataset.teamId); controls.ui.selectedPersonIds = team?.memberIds || []; queueAssignment(state, controls.ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "confirm-team") return action(() => api.confirmTeam(button.dataset.teamId), "队伍已确认，可发放 Code。");
    if (button.dataset.action === "issue-team-code" && window.confirm("确认后，系统将自动发放下一个可用 Code，且不能撤回。")) return action(() => api.issueCode(button.dataset.teamId), "已自动发放下一个可用 Code。");
    if (button.dataset.action === "workshop") return action(() => api.workshopStatus(button.dataset.teamId, "in_progress"), "已标记为 Workshop 中。");
    if (button.dataset.action === "blocked") { const note = window.prompt("记录需要 TA 协助的原因（可留空）", "") ?? ""; return action(() => api.workshopStatus(button.dataset.teamId, "blocked", note), "已标记需要协助。"); }
    if (button.dataset.action === "qualify" && window.confirm("已在 Game Portal 确认该队完成练习赛吗？")) return action(() => api.qualify(button.dataset.teamId), "该队已加入下午比赛池。");
    if (button.dataset.action === "revoke" && window.confirm("确认撤销该队的参赛资格？赛程生成后不可直接撤销。")) { const note = window.prompt("撤销原因（可留空）", "") ?? ""; return action(() => api.revokeQualification(button.dataset.teamId, note, window.prompt("管理员 PIN（部署环境必填）", "") ?? ""), "已撤销参赛资格。"); }
    if (button.dataset.action === "void" && window.confirm("确认作废当前赛程并重新开始分组吗？")) return action(() => api.voidTournament(window.prompt("作废原因（可留空）", "") ?? "", window.prompt("管理员 PIN（部署环境必填）", "") ?? ""), "赛程已作废。");
  }, { signal: staffEventAbort.signal });
  root.querySelector("#people-search")?.addEventListener("input", (event) => { controls.ui.peopleQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector("#team-person-search")?.addEventListener("input", (event) => { controls.ui.teamPeopleQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector("#team-picker-search")?.addEventListener("input", (event) => { controls.ui.teamPickerQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector(".event-gates")?.addEventListener("toggle", (event) => { controls.ui.eventGatesOpen = event.currentTarget.open; }, { signal: staffEventAbort.signal });
  root.addEventListener("change", (event) => { if (event.target.matches("[data-dissolution-team]")) { controls.ui.dissolutionActions = { ...(controls.ui.dissolutionActions || {}), [event.target.dataset.dissolutionTeam]: event.target.value }; } }, { signal: staffEventAbort.signal });
  root.querySelector("#code-import")?.addEventListener("submit", (event) => { event.preventDefault(); const codes = String(new FormData(event.target).get("codes") || "").split(/\r?\n/).map((code) => code.trim()).filter(Boolean); action(() => api.importWorkshopCodes(codes), `已导入 ${codes.length} 个官方 Code。`); });
  root.querySelector("#workshop-link")?.addEventListener("submit", (event) => { event.preventDefault(); const url = new FormData(event.target).get("url"); action(() => api.setWorkshopLink(url), "Workshop 链接已保存。"); });
  root.querySelector("#event-gates")?.addEventListener("submit", (event) => { event.preventDefault(); const form = new FormData(event.target); const gates = { selfServiceTeam: form.has("selfServiceTeam"), codeIssuance: form.has("codeIssuance"), qualification: form.has("qualification"), scheduleEditing: form.has("scheduleEditing") }; if (window.confirm("确认更新现场开关吗？关闭后对应入口会立刻停止。")) action(() => api.updateEventGates(gates, form.get("adminPin")), "现场开关已更新。"); });
  root.querySelector("#code-assign")?.addEventListener("submit", (event) => { event.preventDefault(); const teamId = new FormData(event.target).get("teamId"); if (window.confirm("确认后，系统将自动发放下一个可用 Code，且不能撤回。")) action(() => api.issueCode(teamId), "已自动发放下一个可用 Code。"); });
  root.querySelector("#freeze-roster")?.addEventListener("submit", (event) => { event.preventDefault(); const teamIds = [...new FormData(event.target).getAll("teamId")]; if (window.confirm(`确认冻结 ${teamIds.length} 支参赛队伍吗？`)) action(() => api.freezeCompetition(teamIds, new FormData(event.target).get("adminPin")), "比赛名单已冻结。"); });
  root.querySelector("#generate-groups")?.addEventListener("submit", (event) => { event.preventDefault(); const form = new FormData(event.target); action(() => api.tournament(Number(form.get("groupCount")), Number(form.get("qualifiersPerGroup")), form.get("adminPin")), "小组赛赛程已生成。"); });
  root.querySelector("#swap-groups")?.addEventListener("submit", (event) => { event.preventDefault(); const form = new FormData(event.target); if (window.confirm("确认交换两队的小组位置吗？尚未录入的全部小组赛对阵会按新分组重新生成。")) action(() => api.swapTournamentTeams(form.get("firstTeamId"), form.get("secondTeamId"), form.get("adminPin")), "分组已调整，赛程已同步更新。"); });
  root.querySelector("#generate-knockout")?.addEventListener("submit", (event) => { event.preventDefault(); const form = new FormData(event.target); action(() => api.generateKnockout(form.get("adminPin")), "淘汰赛对阵已生成。"); });
  root.querySelectorAll(".score-form").forEach((form) => form.addEventListener("submit", (event) => { event.preventDefault(); const data = new FormData(form); action(() => api.result(data.get("matchId"), data.get("scoreA"), data.get("scoreB"), data.get("adminPin")), "赛果已保存。"); }));
}

function loginView(root, controls) { root.innerHTML = `<div class="mobile-shell staff-login-shell"><header class="staff-login-top"><div><strong>⚽ 现场运营台</strong><small>Agentic Football 北京 MeetUp</small></div><a href="/">参与者入口</a></header><main class="staff-login-main"><section class="staff-login-ticket"><h1>进入现场运营台</h1><form id="staff-login" class="stack"><label>工作台 PIN<input name="staffPin" type="password" required autocomplete="current-password"></label><label>显示昵称<input name="staffNickname" maxlength="24" required placeholder="例如：小王 TA"></label><p class="staff-login-hint">用于现场操作记录。</p><button>进入工作台 <span aria-hidden="true">→</span></button></form></section></main></div>`; root.querySelector("#staff-login").addEventListener("submit", async (event) => { event.preventDefault(); const form = new FormData(event.target); try { await controls.login({ staffPin: form.get("staffPin"), staffNickname: form.get("staffNickname") }); } catch (error) { window.alert(error.message); } }); }
function gateRow(name, label, checked, hint) { return `<label class="check-row"><input name="${name}" type="checkbox" ${checked ? "checked" : ""}><span><strong>${label}</strong><small>${hint}</small></span></label>`; }
function overview(state, teams, qualified, ui) {
  const available = state.codeSummary?.available || 0; const gates = state.event?.gates || {};
  const overCapacity = Math.max(0, teams.length - Number(state.event?.maxWorkshopTeams || 32));
  const next = !state.codeSummary?.total ? { tab: "codes", button: "去导入官方 Code", copy: "先导入 AWS 老师提供的真实 Code，之后才能逐队发放资源。" }
    : teams.some((team) => team.status === "ready_code") ? { tab: "codes", button: "去发放 Code", copy: "有队伍已确认，正等待领取 Workshop 资源。" }
      : state.participants.some((person) => !person.teamId) ? { tab: "grouping", button: "去安排队伍", copy: "还有到场人员没有队伍，先完成编组。" }
        : { tab: "ta", button: "查看 Workshop 进度", copy: available ? "编组已完成，接下来跟进 Workshop 和练习赛。" : "可用 Code 已用完；请现场确认后续队伍安排。" };
  return `<section class="page-heading"><p class="eyebrow">总览</p><h1>下一步一眼可见</h1><p>同一工作人员可在底部切换组队、发码、TA 与比赛。</p></section><section class="metric-grid"><article><span>已登记</span><strong>${state.participants.length}</strong></article><article><span>草稿队伍</span><strong>${teams.length}</strong></article><article><span>待发 Code</span><strong>${teams.filter((t) => t.status === "ready_code").length}</strong></article><article><span>可用 Code</span><strong>${available}</strong></article><article><span>可参赛</span><strong>${qualified}</strong></article></section>${overCapacity ? `<section class="card notice"><strong>当前有 ${teams.length} 支草稿队，超过 ${state.event.maxWorkshopTeams} 套资源 ${overCapacity} 队。</strong><p>请在组队页将 ${overCapacity} 名成员加入已有队伍后，再确认与发放 Code。</p><button type="button" data-tab="grouping">去合并队伍</button></section>` : ""}<section class="card next-action"><p class="eyebrow">现在先做什么</p><h2>${e(next.button)}</h2><p>${e(next.copy)}</p><button type="button" data-tab="${next.tab}">${e(next.button)}</button>${state.tournament ? '<a class="display-link" href="/display" target="_blank" rel="noreferrer">打开现场大屏</a>' : ""}</section><details class="card event-gates" ${ui.eventGatesOpen ? "open" : ""}><summary><span><strong>活动设置</strong><small>开关自助组队、发码、资格确认与赛程编辑</small></span><span aria-hidden="true">⌄</span></summary><form id="event-gates" class="stack"><p class="hint">仅在需要收口或处理现场例外时展开。关闭后对应操作立即不可用。</p>${gateRow("selfServiceTeam", "临时开放自助组队", gates.selfServiceTeam === true, "仅配合专用入口使用")}${gateRow("codeIssuance", "允许发放 Code", gates.codeIssuance !== false, "关闭后，不再向新队伍发放资源")}${gateRow("qualification", "允许确认参赛资格", gates.qualification !== false, "关闭后，TA 不能再增删下午比赛队伍")}${gateRow("scheduleEditing", "允许调整名单与赛程", gates.scheduleEditing !== false, "关闭后，不能冻结、重分组、交换或作废赛程")}<label>管理员 PIN（部署环境必填）<input name="adminPin" type="password"></label><button>保存现场开关</button></form></details>`;
}
function activeTeams(state) { return state.teams.filter((team) => team.status !== "dissolved"); }
function teamById(state, id) { return state.teams.find((team) => team.id === id); }
function personStatus(state, person) { const current = person.teamId ? teamById(state, person.teamId) : null; return current ? `${current.teamNumber} · ${status(current)}` : "无队"; }
function scanResult(state, ui) {
  if (!ui.scanResultRaw) return "";
  const person = state.participants.find((item) => item.id === ui.scanResultPersonId) || queryPeople(state, ui.scanResultRaw)[0];
  if (!person) return `<section class="scan-result scan-result-miss" aria-live="polite"><p class="eyebrow">扫描结果</p><h2>未找到参与者</h2><p>编号 ${e(ui.scanResultRaw)} 尚未登记。请核对二维码，或改用手动搜索。</p><button type="button" data-action="scan-again" class="secondary">重新扫码</button></section>`;
  const team = person.teamId ? teamById(state, person.teamId) : null;
  const resource = team ? resourceState(state, team) : null;
  return `<section class="scan-result" aria-live="polite"><p class="eyebrow">扫描结果</p><h2>${e(person.nickname)}</h2><p>${e(person.staffShortId)} · ${e(personStatus(state, person))}</p>${resource ? `<small>${e(resource.label)}</small>` : ""}<div class="button-row"><button type="button" data-action="select-scan-result" data-person-id="${e(person.id)}">选中并调度</button>${team ? `<button type="button" data-action="open-scan-result-team" data-team-id="${e(team.id)}" class="secondary">查看 ${e(team.teamNumber)}</button>` : ""}<button type="button" data-action="scan-again" class="text-button">重新扫码</button></div></section>`;
}
function queryPeople(state, query, filter = "all", excludeTeamId = "") {
  const key = String(query || "").trim().toLowerCase(); const numberKey = key.replace(/^p[-\s]?/, "").replace(/^0+/, "");
  return state.participants.filter((person) => {
    const number = person.staffShortId.toLowerCase().replace(/^p-?0*/, "");
    const match = !key || person.nickname.toLowerCase().includes(key) || person.staffShortId.toLowerCase().includes(key) || (numberKey && number.includes(numberKey));
    const groupMatch = filter === "all" || (filter === "unassigned" ? !person.teamId : Boolean(person.teamId));
    return match && groupMatch && person.teamId !== excludeTeamId;
  });
}
function queryTeams(state, query = "", filter = "all", selectedIds = []) {
  const key = String(query || "").trim().toLowerCase(); const compactKey = key.replace(/[^\p{L}\p{N}]/gu, "");
  return activeTeams(state).filter((team) => {
    const nextCount = targetCapacity(state, team, selectedIds); const canJoin = nextCount <= 3;
    const groupMatch = filter === "all" || (filter === "available" ? canJoin : !canJoin);
    const searchable = [team.teamNumber, ...team.members.flatMap((member) => [member.nickname, member.staffShortId])].join(" ").toLowerCase();
    const compactSearchable = searchable.replace(/[^\p{L}\p{N}]/gu, "");
    return groupMatch && (!key || searchable.includes(key) || (compactKey && compactSearchable.includes(compactKey)));
  });
}
function resourceState(state, team) {
  const summary = state.codeSummary || { total: 0, available: 0 };
  if (team.codeIssuedAt || team.teamCodeAssigned) return { tone: "issued", label: "已发放 Workshop Code", copy: "资源已绑定给当前队伍成员；成员离开后将不能继续查看。" };
  if (team.status === "draft") return { tone: "neutral", label: "请先确认队伍", copy: "确认后才能发放 Workshop Code。" };
  if (!summary.total) return { tone: "neutral", label: "尚未导入官方 Code", copy: "请由 Admin 导入 AWS 老师提供的真实 Code。" };
  if (state.event?.gates?.codeIssuance === false) return { tone: "paused", label: "现场已暂停发放 Code", copy: "管理员可在活动设置中重新开启。" };
  if (!summary.available) return { tone: "paused", label: "当前没有可用 Code", copy: "不向选手显示该状态；由工作人员现场决定后续安排。" };
  return { tone: "ready", label: "可立即发放资源", copy: `还剩 ${summary.available} 个可用 Code；系统会自动取下一个。` };
}
function candidateGroup(state, people, selected, title, copy) {
  if (!people.length) return "";
  return `<div class="candidate-group"><div class="candidate-group-heading"><strong>${e(title)} ${people.length}</strong><small>${e(copy)}</small></div>${people.map((person) => personRow(state, person, selected.includes(person.id))).join("")}</div>`;
}
function togglePerson(ui, personId) { const selected = new Set(ui.selectedPersonIds || []); if (selected.has(personId)) selected.delete(personId); else if (selected.size < 3) selected.add(personId); ui.selectedPersonIds = [...selected]; }
function targetCapacity(state, team, selectedIds) { const selected = new Set(selectedIds || []); return team.memberIds.filter((id) => !selected.has(id)).length + [...selected].filter((id) => !team.memberIds.includes(id)).length; }
function queueAssignment(state, ui, targetTeamId) { const participantIds = ui.selectedPersonIds || []; if (!participantIds.length) return; const selected = new Set(participantIds); const sourceTeams = [...new Set(state.participants.filter((person) => selected.has(person.id) && person.teamId && person.teamId !== targetTeamId).map((person) => person.teamId))].map((id) => teamById(state, id)).filter(Boolean); const empties = sourceTeams.filter((team) => team.memberIds.every((id) => selected.has(id))); const defaults = { ...(ui.dissolutionActions || {}) }; empties.forEach((team) => { if (!defaults[team.id]) defaults[team.id] = team.workshopCodeId ? "keep" : "dissolve"; }); ui.dissolutionActions = defaults; ui.pendingAssignment = { participantIds, targetTeamId, emptyTeamIds: empties.map((team) => team.id) }; }
function peopleBoard(state, ui) {
  const selected = ui.selectedPersonIds || []; const filter = ui.peopleFilter || "all"; const shown = queryPeople(state, ui.peopleQuery, filter);
  return `<section class="card dispatch-board"><div class="button-row"><button type="button" data-action="scan" class="secondary">扫描参与者二维码</button></div><label>查找人员<input id="people-search" autocomplete="off" placeholder="昵称、001 或 P-001" value="${e(ui.peopleQuery || "")}"><small>扫码不可用时，可直接按昵称或人员编号查找。</small></label><div id="scanner" class="scanner"></div>${scanResult(state, ui)}<div class="filter-row"><button data-people-filter="all" class="${filter === "all" ? "active" : ""}">全部 ${state.participants.length}</button><button data-people-filter="unassigned" class="${filter === "unassigned" ? "active" : ""}">无队 ${state.participants.filter((person) => !person.teamId).length}</button><button data-people-filter="assigned" class="${filter === "assigned" ? "active" : ""}">有队 ${state.participants.filter((person) => person.teamId).length}</button></div><div class="dispatch-list">${shown.map((person) => personRow(state, person, selected.includes(person.id))).join("") || '<p class="hint">没有匹配的人员。</p>'}</div></section>${selected.length ? selectionTray(state, ui) : ""}`;
}
function personRow(state, person, selected) { return `<button type="button" class="dispatch-person-row ${selected ? "is-selected" : ""}" data-action="toggle-person" data-person-id="${e(person.id)}" aria-pressed="${selected}"><span><strong>${e(person.nickname)}</strong><small>${e(person.staffShortId)} · ${e(personStatus(state, person))}</small></span><span class="dispatch-check">${selected ? "已选" : "选择"}</span></button>`; }
function selectionTray(state, ui) { const selected = (ui.selectedPersonIds || []).map((id) => state.participants.find((person) => person.id === id)).filter(Boolean); return `<section class="selection-tray"><div><strong>已选择 ${selected.length} / 3 人</strong><small>${selected.map((person) => `${e(person.nickname)} ${e(person.staffShortId)}`).join("、")}</small></div><div><button data-action="new-team">下一步：确认新队</button><button data-action="open-team-picker" class="secondary">加入队伍</button><button data-action="remove-selected" class="secondary">移出队伍</button><button data-action="clear-people" class="text-button">清除</button></div></section>`; }
function teamBoard(state) { const teams = activeTeams(state); return `<section class="card dispatch-board"><div class="team-board-list">${teams.map((team) => `<button type="button" class="team-board-card" data-action="open-team-config" data-team-id="${e(team.id)}"><span class="team-board-identity"><strong>${e(team.teamNumber)}</strong><small>${team.members.map((member) => `${e(member.nickname)} · ${e(member.staffShortId)}`).join("、") || "暂无成员"}</small></span><span class="team-board-meta"><em>${team.memberIds.length} / 3</em><small>${e(status(team))}${team.teamCodeAssigned ? " · 已发 Code" : ""}</small></span><span class="team-board-action" aria-hidden="true">管理 ›</span></button>`).join("") || '<p class="hint">暂无活跃队伍。</p>'}</div></section>`; }
function allocationPanel(state) {
  const allocation = state.allocation || {}; const manual = allocation.manualTeams || []; const automatic = allocation.automaticTeams || []; const free = allocation.freePeople || []; const waitlist = allocation.waitlist || []; const conflicts = allocation.conflicts || []; const suggestions = allocation.lowAttendanceSuggestions || []; const preview = allocation.latestPreview;
  const list = (items, empty, label) => items.length ? `<div class="compact-list">${items.map((item) => `<article><div><strong>${e(item.teamNumber || item.nickname || item.code)}</strong><small>${item.members ? item.members.map((member) => e(member.nickname)).join("、") : e(item.message || item.staffShortId || "")}</small></div><span class="pill">${e(label(item))}</span></article>`).join("")}</div>` : `<p class="hint">${e(empty)}</p>`;
  return `<section class="card allocation-workbench"><p class="eyebrow">人员分配</p><h2>先预览，再发布</h2><p>登记人员先进入自由池；发布前不会创建正式自动队，也不会静默改变已发布结果。</p><div class="metric-grid"><article><span>自由人员</span><strong>${free.length}</strong></article><article><span>人工队</span><strong>${manual.length}</strong></article><article><span>自动队</span><strong>${automatic.length}</strong></article><article><span>候补</span><strong>${waitlist.length}</strong></article></div><div class="button-row"><button data-action="allocation-preview">生成自动分配预览</button>${preview ? `<button data-action="allocation-publish" data-run-id="${e(preview.id)}" class="secondary">发布预览</button>` : ""}</div>${preview ? `<section class="modal-safe-note"><strong>待发布预览</strong><p>seed: ${e(preview.allocationSeed)} · ${e(preview.ruleVersion)} · ${e(preview.executedAt)}</p><p>预览包含 ${preview.result?.teams?.length || 0} 支队与 ${preview.result?.waitlist?.length || 0} 名候补；发布前仍可继续检查。</p></section>` : ""}${conflicts.length ? `<section class="notice"><strong>无法生成分配：发现 ${conflicts.length} 项人工队冲突</strong><ul>${conflicts.map((item) => `<li>${e(item.message)}</li>`).join("")}</ul></section>` : ""}<details><summary>自由人员 · ${free.length}</summary>${list(free, "暂无自由人员", (p) => p.staffShortId)}</details><details><summary>人工队 · ${manual.length}</summary>${list(manual, "暂无人工队", (t) => `${t.memberIds.length}/3 · 核心 ${t.coreMemberIds?.length || 0}`)}</details><details><summary>自动队 · ${automatic.length}</summary>${list(automatic, "发布后自动队会出现在这里", (t) => `${t.memberIds.length}/3 · 自动`)}</details><details><summary>候补 · ${waitlist.length}</summary>${list(waitlist, "暂无候补", (p) => p.waitlistReason || "候补")}</details>${suggestions.length ? `<section class="notice"><strong>低人数人工协商建议</strong><p>当前总人数少于 32；系统不会拆散熟人队。请在取得成员确认后，使用人工拆队或释放成员操作。</p><ul>${suggestions.map((item) => `<li>${e(item.message)}</li>`).join("")}</ul></section>` : ""}</section>`;
}
function grouping(state, ui) { const tab = ui.groupingTab || "people"; return `${allocationPanel(state)}<div class="grouping-tabs"><button data-grouping-tab="people" class="${tab === "people" ? "active" : ""}">人员 ${state.participants.length}</button><button data-grouping-tab="teams" class="${tab === "teams" ? "active" : ""}">队伍 ${activeTeams(state).length}</button></div>${tab === "people" ? peopleBoard(state, ui) : teamBoard(state)}${ui.teamPickerOpen ? teamPicker(state, ui) : ""}${ui.pendingAssignment ? assignmentConfirm(state, ui) : ""}${ui.teamConfigId && !ui.teamPickerOpen && !ui.pendingAssignment ? teamConfig(state, ui) : ""}`; }
function teamPicker(state, ui) {
  const selected = ui.selectedPersonIds || []; const filter = ui.teamPickerFilter || "all";
  const all = queryTeams(state, ui.teamPickerQuery, "all", selected); const available = all.filter((team) => targetCapacity(state, team, selected) <= 3); const full = all.filter((team) => targetCapacity(state, team, selected) > 3);
  const shown = queryTeams(state, ui.teamPickerQuery, filter, selected);
  return `<div class="modal-backdrop"><section class="dispatch-modal picker-modal" role="dialog" aria-modal="true" aria-label="选择目标队伍"><div class="modal-header"><div><h2>加入哪支队伍？</h2></div><button data-action="close-team-picker" class="text-button">关闭</button></div><div class="modal-selection-summary"><strong>将调整</strong><span>${selected.map((id) => state.participants.find((person) => person.id === id)).filter(Boolean).map((person) => `${e(person.nickname)} · ${e(person.staffShortId)}`).join("、")}</span></div><label>查找目标队伍<input id="team-picker-search" autocomplete="off" placeholder="T-001、001 或成员昵称" value="${e(ui.teamPickerQuery || "")}"></label><div class="filter-row team-picker-filter"><button data-team-picker-filter="all" class="${filter === "all" ? "active" : ""}">全部 ${all.length}</button><button data-team-picker-filter="available" class="${filter === "available" ? "active" : ""}">可加入 ${available.length}</button><button data-team-picker-filter="full" class="${filter === "full" ? "active" : ""}">容量不足 ${full.length}</button></div><div class="team-picker-list">${shown.map((team) => { const nextCount = targetCapacity(state, team, selected); const canJoin = nextCount <= 3; const resource = resourceState(state, team); return `<button data-action="choose-team" data-team-id="${e(team.id)}" ${canJoin ? "" : "disabled"}><span><strong>${e(team.teamNumber)}</strong><small>${team.members.map((member) => e(member.nickname)).join("、") || "暂无成员"}</small></span><span class="team-picker-meta"><em>${nextCount} / 3</em><small>${canJoin ? resource.label : "容量不足"}</small></span></button>`; }).join("") || '<p class="hint">没有匹配的队伍。</p>'}</div></section></div>`;
}
function assignmentConfirm(state, ui) {
  const pending = ui.pendingAssignment; const people = pending.participantIds.map((id) => state.participants.find((person) => person.id === id)).filter(Boolean); const target = pending.targetTeamId === "new" ? null : teamById(state, pending.targetTeamId); const heading = pending.targetTeamId === "new" ? "确认组成新队" : target ? `确认加入 ${target.teamNumber}` : "确认移出队伍"; const empties = (pending.emptyTeamIds || []).map((id) => teamById(state, id)).filter(Boolean);
  const commitLabel = pending.targetTeamId === "new" ? "确认创建队伍" : pending.targetTeamId ? "确认加入队伍" : "确认移出队伍";
  const pendingLabel = ui.actionPending ? (ui.pendingActionLabel || "正在保存…") : commitLabel;
  return `<div class="modal-backdrop"><section class="dispatch-modal commit-modal" role="dialog" aria-modal="true" aria-label="确认人员调度"><div class="modal-header"><div><h2>${heading}</h2><p>这一步会更新人员与队伍的关联。</p></div><button data-action="close-assignment" class="text-button" ${ui.actionPending ? "disabled" : ""}>取消</button></div><div class="modal-selection-summary"><strong>涉及人员</strong><span>${people.map((person) => `${e(person.nickname)} · ${e(person.staffShortId)}`).join("、")}</span></div>${target ? `<div class="modal-target-summary"><strong>目标队伍</strong><span>${e(target.teamNumber)} · 执行后 ${targetCapacity(state, target, people.map((person) => person.id))} / 3 人</span></div>` : ""}${empties.length ? `<div class="dissolution-list"><h3>以下队伍会因移走最后一名成员而解散</h3><p>已领 Code 的队伍会保留为已消耗；如需重新发放，请由 Admin 在资源管理中回收。</p>${empties.map((team) => `<div class="modal-safe-note">${e(team.teamNumber)}${team.workshopCodeId ? " · Code 保留为已消耗" : " · 直接解散"}</div>`).join("")}</div>` : '<p class="modal-safe-note">不会解散其他队伍。</p>'}<button data-action="confirm-assignment" class="confirm-dispatch" ${ui.actionPending ? "disabled aria-busy=\"true\"" : ""}>${pendingLabel}</button></section></div>`;
}
function teamConfig(state, ui) {
  const team = teamById(state, ui.teamConfigId); if (!team) return "";
  const filter = ui.teamPeopleFilter || "all"; const selected = ui.selectedPersonIds || [];
  const candidates = queryPeople(state, ui.teamPeopleQuery, filter, team.id);
  const all = state.participants.filter((person) => person.teamId !== team.id);
  const unassigned = all.filter((person) => !person.teamId);
  const assigned = all.filter((person) => person.teamId);
  const resource = resourceState(state, team); const canIssue = resource.tone === "ready"; const canConfirm = team.status === "draft";
  const groupedCandidates = filter === "all" ? `${candidateGroup(state, candidates.filter((person) => !person.teamId), selected, "无队人员", "优先安排；也可直接加入此队")}${candidateGroup(state, candidates.filter((person) => person.teamId), selected, "已在其他队", "选择后会在确认页说明转队影响")}` : candidates.map((person) => personRow(state, person, selected.includes(person.id))).join("");
  return `<div class="modal-backdrop"><section class="dispatch-modal team-config-modal" role="dialog" aria-modal="true" aria-label="修改队伍配置"><div class="modal-header"><div><h2>${e(team.teamNumber)}</h2><p>${team.memberIds.length} / 3 人 · ${e(status(team))}</p></div><button data-action="close-team-config" class="text-button">关闭</button></div><section class="team-resource-card ${resource.tone}"><div><strong>${e(resource.label)}</strong><small>${e(resource.copy)}</small></div><span class="resource-actions">${canConfirm ? `<button data-action="confirm-team" data-team-id="${e(team.id)}" class="secondary">确认队伍</button>` : ""}${canIssue ? `<button data-action="issue-team-code" data-team-id="${e(team.id)}">发放下一个 Code</button>` : ""}</span></section><section class="modal-section"><div class="modal-section-heading"><div><h3>当前成员</h3></div><span>${team.memberIds.length} / 3</span></div><div class="config-member-list">${team.members.map((member) => `<article><span><strong>${e(member.nickname)}</strong><small>${e(member.staffShortId)}</small></span><span><button data-action="team-transfer-member" data-person-id="${e(member.id)}" class="secondary">转队</button><button data-action="team-remove-member" data-person-id="${e(member.id)}" class="secondary">移出</button></span></article>`).join("")}</div></section><section class="modal-section"><div class="modal-section-heading"><div><h3>添加成员</h3><p>完整列表可浏览；搜索和筛选只用于加速。</p></div><span>可选 ${all.length}</span></div><label>查找人员<input id="team-person-search" autocomplete="off" placeholder="昵称、001 或 P-001" value="${e(ui.teamPeopleQuery || "")}"></label><div class="filter-row team-people-filter"><button data-team-people-filter="all" class="${filter === "all" ? "active" : ""}">全部 ${all.length}</button><button data-team-people-filter="unassigned" class="${filter === "unassigned" ? "active" : ""}">无队 ${unassigned.length}</button><button data-team-people-filter="assigned" class="${filter === "assigned" ? "active" : ""}">有队 ${assigned.length}</button></div><div class="candidate-list">${groupedCandidates || '<p class="hint">没有匹配的人员。</p>'}</div>${selected.length ? `<button data-action="team-add-selected" data-team-id="${e(team.id)}" ${targetCapacity(state, team, selected) <= 3 ? "" : "disabled"}>将已选 ${selected.length} 人加入此队${targetCapacity(state, team, selected) <= 3 ? "" : "（容量不足）"}</button>` : ""}</section><section class="danger-zone"><h3>解散队伍</h3><p>移出全部成员后立即解散；已领 Code 默认保留为已消耗，Admin 可在资源管理中回收。</p><button data-action="dissolve-team" data-team-id="${e(team.id)}" class="secondary">解散 ${e(team.teamNumber)}</button></section></section></div>`;
}
function codeTab(state, teams) { const ready = teams.filter((team) => !team.codeIssuedAt && ["draft", "ready_code"].includes(team.status)); const issued = teams.filter((team) => team.codeIssuedAt); const summary = state.codeSummary || { total: 0, available: 0, issued: 0 }; const open = state.event?.gates?.codeIssuance !== false; return `<section class="page-heading"><p class="eyebrow">Workshop Code</p><h1>导入、库存与发放记录</h1><p>日常发放可直接在队伍弹窗完成；这里保留批量导入、库存全貌和备用发放入口。</p></section><section class="card"><h2>Workshop 链接</h2><form id="workshop-link" class="stack"><label>活动统一链接<input name="url" type="url" value="${e(state.event.workshopUrl)}" placeholder="https://…"></label><button>保存链接</button></form><p class="hint">发码后的队伍会看到“进入 Workshop”和“复制链接”。</p></section><section class="card"><h2>导入官方 Code</h2><form id="code-import" class="stack"><label>每行一个 Code<textarea name="codes" rows="4" placeholder="粘贴 AWS 老师提供的 32 个真实 Code"></textarea></label><button ${summary.issued ? "disabled" : ""}>批量导入</button></form><p class="hint">已导入 ${summary.total} 个 · 可用 ${summary.available} 个 · 已发放 ${summary.issued} 个</p></section><section class="card"><h2>备用发放入口</h2><p class="hint">正常情况下请在目标队伍的管理弹窗发放；这里适合快速补发处理。</p><form id="code-assign" class="stack"><label>队伍<select name="teamId">${ready.map((team) => `<option value="${e(team.id)}">${members(team)}</option>`).join("")}</select></label><button ${!open || !ready.length || !summary.available ? "disabled" : ""}>自动发放下一个可用 Code</button></form>${open ? "" : '<p class="hint">现场开关已关闭 Code 发放。</p>'}</section><section class="card"><h2>发放记录</h2><ul class="plain-list">${issued.map((team) => `<li>${members(team)} · 已发放</li>`).join("") || "暂无"}</ul></section>`; }
function taTab(state, teams, ui) { const filter = ui.taFilter || "all"; const shown = teams.filter((team) => team.codeIssuedAt && (filter === "all" || (filter === "ta_qualified" ? team.qualificationStatus === "ta_qualified" : team.workshopStatus === filter))); const open = state.event?.gates?.qualification !== false; return `<section class="page-heading"><p class="eyebrow">Workshop / TA</p><h1>练习赛跑完，即可确认</h1><p>TA 在 Game Portal 核验练习赛记录后，一键将队伍加入下午比赛池。</p></section><section class="filter-row"><button data-filter="all" class="${filter === "all" ? "active" : ""}">全部</button><button data-filter="in_progress" class="${filter === "in_progress" ? "active" : ""}">进行中</button><button data-filter="blocked" class="${filter === "blocked" ? "active" : ""}">需协助</button><button data-filter="ta_qualified" class="${filter === "ta_qualified" ? "active" : ""}">已参赛</button></section>${open ? "" : '<p class="notice">下午比赛资格已停止确认。</p>'}<section class="compact-list card">${shown.map((team) => `<article><div><strong>${members(team)}</strong><small>${status(team)}${team.workshopNote ? ` · ${e(team.workshopNote)}` : ""}</small></div><div>${team.qualificationStatus === "ta_qualified" ? `<span class="pill">已确认</span><button data-action="revoke" data-team-id="${e(team.id)}" class="secondary" ${open ? "" : "disabled"}>撤销</button>` : `<button data-action="workshop" data-team-id="${e(team.id)}">Workshop 中</button><button data-action="blocked" data-team-id="${e(team.id)}" class="secondary">需要协助</button><button data-action="qualify" data-team-id="${e(team.id)}" ${open ? "" : "disabled"}>确认可参赛</button>`}</div></article>`).join("") || "暂无"}</section>`; }
function competition(state, teams) { const eligible = teams.filter((team) => team.qualificationStatus === "ta_qualified"); const frozen = state.competition?.frozenTeamIds || []; const tournament = state.tournament; const open = state.event?.gates?.scheduleEditing !== false; const closed = open ? "" : '<p class="notice">现场开关已锁定名单和赛程；赛果仍可继续录入。</p>'; if (!frozen.length && !tournament) return `<section class="page-heading"><p class="eyebrow">比赛</p><h1>先冻结参赛名单</h1><p>只有 TA 已确认的队伍可以进入下午比赛。</p></section>${closed}<form id="freeze-roster" class="stack card">${eligible.map((team) => `<label class="check-row"><input type="checkbox" name="teamId" value="${e(team.id)}" checked>${members(team)}</label>`).join("") || "暂无资格队"}<label>管理员 PIN（部署环境必填）<input name="adminPin" type="password"></label><button ${!open || eligible.length < 2 ? "disabled" : ""}>冻结名单</button></form>`; if (frozen.length && !tournament) return `<section class="page-heading"><p class="eyebrow">比赛</p><h1>已冻结 ${frozen.length} 支队伍</h1><p>配置小组数和每组晋级名额后生成赛程。</p></section>${closed}<form id="generate-groups" class="stack card"><label>小组数量<input name="groupCount" type="number" min="1" max="8" value="${Math.ceil(frozen.length / 4)}"></label><label>每组晋级<select name="qualifiersPerGroup"><option value="2">前 2 名</option><option value="1">前 1 名</option></select></label><label>管理员 PIN（部署环境必填）<input name="adminPin" type="password"></label><button ${open ? "" : "disabled"}>生成小组赛</button></form>`; return tournamentView(tournament, open); }
function tournamentView(tournament, scheduleEditingOpen) { const groups = tournament.groups.map((group) => `<section class="card"><h2>${e(group.id)} 组积分榜</h2><table class="standings"><thead><tr><th>队伍</th><th>赛</th><th>胜</th><th>平</th><th>负</th><th>净胜球</th><th>分</th></tr></thead><tbody>${group.standings.map((row) => `<tr><td>${e(row.label)}</td><td>${row.played}</td><td>${row.won}</td><td>${row.drawn}</td><td>${row.lost}</td><td>${row.goalDifference}</td><td><strong>${row.points}</strong></td></tr>`).join("")}</tbody></table></section>`).join(""); const groupMatches = tournament.matches.map((match) => scoreForm(match, "小组赛")).join(""); const adjustable = scheduleEditingOpen && tournament.status === "group" && !tournament.matches.some((match) => match.status === "completed"); const firstDefault = tournament.groups[0]?.standings[0]?.teamId; const secondDefault = tournament.groups[1]?.standings[0]?.teamId || tournament.groups[0]?.standings[1]?.teamId; const teamChoices = (selected) => tournament.groups.flatMap((group) => group.standings.map((row) => `<option value="${e(row.teamId)}" ${row.teamId === selected ? "selected" : ""}>${e(group.id)} 组 · ${e(row.label)}</option>`)).join(""); const adjustment = adjustable ? `<form id="swap-groups" class="stack card"><h2>人工调整分组</h2><p>选择两支来自不同小组的队伍进行交换；系统会重排尚未开始的小组赛对阵。</p><label>第一支队伍<select name="firstTeamId">${teamChoices(firstDefault)}</select></label><label>第二支队伍<select name="secondTeamId">${teamChoices(secondDefault)}</select></label><label>管理员 PIN（部署环境必填）<input name="adminPin" type="password"></label><button>交换两队的小组位置</button></form>` : ""; const knockout = tournament.knockoutMatches?.length ? `<section class="card"><h2>淘汰赛</h2><div class="compact-list">${tournament.knockoutMatches.map((match) => scoreForm(match, `第 ${match.round} 轮`)).join("")}</div></section>` : `<form id="generate-knockout" class="stack card"><p>小组赛全部完成后，按积分榜自动生成淘汰赛。</p><label>管理员 PIN（部署环境必填）<input name="adminPin" type="password"></label><button ${tournament.matches.some((match) => match.status !== "completed") ? "disabled" : ""}>生成淘汰赛</button></form>`; return `<section class="page-heading"><p class="eyebrow">比赛</p><h1>${tournament.status === "knockout" ? "淘汰赛进行中" : "小组赛进行中"}</h1><p>小组赛胜 3 分、平 1 分、负 0 分；同分时依次比较净胜球、进球数。</p><div class="button-row"><a class="display-link" href="/display" target="_blank" rel="noreferrer">打开现场大屏</a>${scheduleEditingOpen ? '<button data-action="void" class="secondary">作废并重新分组</button>' : ""}</div></section>${adjustment}${groups}<section class="card"><h2>小组赛赛果</h2><div class="compact-list">${groupMatches}</div></section>${knockout}`; }
function auditTab(log, ui) { const filter = ui.auditFilter || "all"; const choices = [{ id: "all", label: "全部" }, { id: "team", label: "队伍" }, { id: "code", label: "Code" }, { id: "workshop", label: "Workshop" }, { id: "competition", label: "比赛" }]; const shown = log.filter((entry) => filter === "all" || entry.action.startsWith(filter) || entry.objectType === filter || (filter === "competition" && /^(competition|tournament|match)\./.test(entry.action))).slice(0, 100); return `<section class="page-heading"><p class="eyebrow">操作记录</p><h1>现场变更可追溯</h1><p>仅显示最近 100 条操作；用于工作人员之间快速交接，不需要切换账号。</p></section><section class="filter-row">${choices.map((item) => `<button data-audit-filter="${item.id}" class="${filter === item.id ? "active" : ""}">${item.label}</button>`).join("")}</section><section class="compact-list card">${shown.map((entry) => `<article class="audit-entry"><div><strong>${e(auditLabel(entry.action))}</strong><small>${e(entry.staffNickname)} · ${e(new Date(entry.at).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" }))}${entry.reason ? ` · ${e(entry.reason)}` : ""}</small></div></article>`).join("") || "暂无记录"}</section>`; }
function auditLabel(action) { return ({ "participant.registered": "参与者完成登记", "participant.rebound": "参与者恢复设备状态", "team.self.created": "参与者创建队伍", "team.self.joined": "参与者加入队伍", "team.created": "工作人员创建队伍", "team.members.updated": "工作人员调整队伍", "team.removed": "工作人员解散队伍", "team.confirmed": "工作人员确认队伍", "codes.imported": "导入官方 Code", "code.issued": "发放 Workshop Code", "workshop.link.updated": "更新 Workshop 链接", "workshop.status.updated": "更新 Workshop 状态", "team.ta.qualified": "TA 确认可参赛", "team.ta.qualification.revoked": "撤销参赛资格", "competition.roster.frozen": "冻结比赛名单", "competition.roster.unfrozen": "解除比赛名单冻结", "tournament.generated": "生成小组赛", "tournament.groups.swapped": "调整小组分配", "match.result.recorded": "录入比赛赛果", "tournament.knockout.generated": "生成淘汰赛", "tournament.voided": "作废赛程", "staff.session.created": "工作人员进入工作台" })[action] || action; }
function scoreForm(match, caption) { if (match.status === "bye") return `<article><div><strong>${e(caption)} · ${e(match.teamALabel)} vs ${e(match.teamBLabel)}</strong><small>轮空晋级：${e(match.winnerLabel)}</small></div></article>`; if (!match.teamAId || !match.teamBId) return `<article><div><strong>${e(caption)}</strong><small>等待上一轮结果</small></div></article>`; return `<form class="score-form"><input type="hidden" name="matchId" value="${e(match.id)}"><strong>${e(caption)} · ${e(match.teamALabel)} vs ${e(match.teamBLabel)}</strong><input name="scoreA" inputmode="numeric" value="${match.scoreA ?? ""}" placeholder="A"><span>:</span><input name="scoreB" inputmode="numeric" value="${match.scoreB ?? ""}" placeholder="B"><input name="adminPin" type="password" placeholder="管理员 PIN"><button>${match.status === "completed" ? "更正" : "保存"}</button></form>`; }
function startScanner(root, state, controls, api, notice) {
  const box = root.querySelector("#scanner");
  controls.ui.scannerOpen = true;
  if (!("BarcodeDetector" in window) || !navigator.mediaDevices?.getUserMedia) {
    controls.ui.scannerOpen = false;
    notice.textContent = "此手机不支持扫码，请使用昵称或人员编号搜索。";
    box.innerHTML = '<p class="hint">请改用上方的昵称或人员编号搜索。</p>';
    return;
  }
  box.innerHTML = `<section class="scanner-panel" aria-live="polite"><div class="scanner-toolbar"><strong>正在扫描参与者二维码</strong><button type="button" data-action="stop-scan" class="secondary">关闭扫描</button></div><video autoplay playsinline muted></video><p class="hint">将参与者的个人二维码放入镜头中；也可随时关闭后手动搜索。</p></section>`;
  const video = box.querySelector("video"); const Detector = window.BarcodeDetector; const detector = new Detector({ formats: ["qr_code"] });
  navigator.mediaDevices.getUserMedia({ video: { facingMode: "environment" } }).then((stream) => {
    controls.ui.scannerStream = stream; video.srcObject = stream;
    const scan = async () => {
      if (!controls.ui.scannerStream) return;
      try {
        const codes = await detector.detect(video);
        if (codes[0]?.rawValue) {
          const rawValue = String(codes[0].rawValue).trim();
          controls.ui.peopleQuery = rawValue;
          controls.ui.scanResultRaw = rawValue;
          controls.ui.scanResultPersonId = queryPeople(state, rawValue)[0]?.id || "";
          closeScanner(controls.ui);
          renderStaff(root, state, api, controls);
        } else requestAnimationFrame(scan);
      } catch { requestAnimationFrame(scan); }
    };
    requestAnimationFrame(scan);
  }).catch(() => {
    controls.ui.scannerOpen = false;
    notice.textContent = "无法打开相机，请关闭扫描后使用昵称或人员编号搜索。";
    box.innerHTML = '<p class="hint">无法打开相机。请改用上方的昵称或人员编号搜索。</p>';
  });
}
function stopScanner(ui) { ui.scannerStream?.getTracks?.().forEach((track) => track.stop()); ui.scannerStream = null; }
function closeScanner(ui) { stopScanner(ui); ui.scannerOpen = false; }

export function renderStaff(root, state, api, controls) {
  if (!controls.loggedIn) return loginView(root, controls);
  if (!controls.ui.scannerOpen) stopScanner(controls.ui);
  const ui = controls.ui; const tab = ui.tab || "overview"; const teams = activeTeams(state);
  const content = { overview: staffOverview(state), grouping: grouping(state, ui), workshop: staffWorkshop(state), competition: staffCompetition(state) }[tab] || staffOverview(state);
  root.innerHTML = `<div class="staff-shell"><header class="staff-top"><div><strong>⚽ 现场运营台</strong><small>${e(state.event?.name || "北京 MeetUp")}</small></div><div class="top-actions"><button type="button" class="text-button" data-feedback>反馈</button><button type="button" class="text-button" data-action="admin-access">更多</button><button type="button" class="text-button" data-action="logout">退出</button></div></header><p class="notice" aria-live="polite"></p><main>${content}</main><nav class="bottom-tabs bottom-tabs-four"><button data-tab="overview" class="${tab === "overview" ? "active" : ""}">现场</button><button data-tab="grouping" class="${tab === "grouping" ? "active" : ""}">组队</button><button data-tab="workshop" class="${tab === "workshop" ? "active" : ""}">Workshop</button><button data-tab="competition" class="${tab === "competition" ? "active" : ""}">比赛</button></nav>${ui.adminAccessOpen ? adminAccessModal() : ""}</div>`;
  ui.staffEventAbort?.abort(); const abort = new AbortController(); ui.staffEventAbort = abort;
  const notice = root.querySelector(".notice");
  const action = async (fn, ok, trigger, pendingLabel = "正在保存…") => {
    if (ui.actionPending) return; ui.actionPending = true;
    const original = trigger?.textContent; if (trigger) { trigger.disabled = true; trigger.textContent = pendingLabel; }
    try { await fn(); await controls.refresh(); const current = document.querySelector(".notice"); if (current) current.textContent = ok; }
    catch (error) { notice.textContent = error.message; }
    finally { ui.actionPending = false; if (trigger?.isConnected) { trigger.disabled = false; trigger.textContent = original; } }
  };
  root.addEventListener("click", (event) => {
    const button = event.target.closest("button"); if (!button) return;
    if (button.dataset.tab) { closeScanner(ui); ui.tab = button.dataset.tab; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "logout") { closeScanner(ui); return controls.logout(); }
    if (button.dataset.action === "admin-access") { ui.adminAccessOpen = true; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-admin-access") { ui.adminAccessOpen = false; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "allocation-preview") { const seed = window.prompt("可选：输入 allocationSeed 以复盘；留空则生成新 seed", ""); if (seed === null) return; return action(() => api.allocationPreview(seed), "已生成未发布的自动分配预览，请核对后再发布。", button, "正在生成预览…"); }
    if (button.dataset.action === "allocation-publish") { if (!window.confirm("确认发布此预览？发布后不会因刷新或登记而静默重排。")) return; return action(() => api.publishAllocation(button.dataset.runId), "分配已发布；后续变化需要再次显式预览并发布。", button, "正在发布…"); }
    if (button.dataset.action === "scan") return startScanner(root, state, controls, api, notice);
    if (button.dataset.action === "stop-scan") { closeScanner(ui); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "scan-again") { ui.scanResultRaw = ""; ui.scanResultPersonId = ""; ui.peopleQuery = ""; return startScanner(root, state, controls, api, notice); }
    if (button.dataset.action === "select-scan-result") { ui.selectedPersonIds = [button.dataset.personId]; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "open-scan-result-team") { ui.groupingTab = "teams"; ui.teamConfigId = button.dataset.teamId; ui.selectedPersonIds = []; ui.tab = "grouping"; return renderStaff(root, state, api, controls); }
    if (button.dataset.groupingTab) { ui.groupingTab = button.dataset.groupingTab; ui.selectedPersonIds = []; ui.teamConfigId = null; return renderStaff(root, state, api, controls); }
    if (button.dataset.peopleFilter) { ui.peopleFilter = button.dataset.peopleFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.teamPeopleFilter) { ui.teamPeopleFilter = button.dataset.teamPeopleFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.teamPickerFilter) { ui.teamPickerFilter = button.dataset.teamPickerFilter; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "toggle-person") { togglePerson(ui, button.dataset.personId); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "clear-people") { ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "new-team") { queueAssignment(state, ui, "new"); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "open-team-picker") { if (!(ui.selectedPersonIds || []).length) return; ui.teamPickerOpen = true; ui.teamPickerQuery = ""; ui.teamPickerFilter = "all"; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-team-picker") { ui.teamPickerOpen = false; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "choose-team") { queueAssignment(state, ui, button.dataset.teamId); ui.teamPickerOpen = false; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "remove-selected") { queueAssignment(state, ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-assignment") { ui.pendingAssignment = null; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "confirm-assignment") { const pending = ui.pendingAssignment; if (!pending) return; return action(() => api.dispatchPeople(pending.participantIds, pending.targetTeamId), "人员与队伍关系已更新。", button).then(() => { ui.selectedPersonIds = []; ui.pendingAssignment = null; ui.teamConfigId = null; }); }
    if (button.dataset.action === "open-team-config") { ui.teamConfigId = button.dataset.teamId; ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "close-team-config") { ui.teamConfigId = null; ui.selectedPersonIds = []; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-add-selected") { queueAssignment(state, ui, button.dataset.teamId); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-remove-member") { ui.selectedPersonIds = [button.dataset.personId]; queueAssignment(state, ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "team-transfer-member") { ui.selectedPersonIds = [button.dataset.personId]; ui.teamPickerOpen = true; ui.teamPickerQuery = ""; ui.teamPickerFilter = "all"; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "dissolve-team") { const team = teamById(state, button.dataset.teamId); ui.selectedPersonIds = team?.memberIds || []; queueAssignment(state, ui, ""); return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "confirm-team") return action(() => api.confirmTeam(button.dataset.teamId), "队伍已确认，可以发放 Code。", button);
    if (button.dataset.action === "issue-team-code" && window.confirm("确认后，系统将自动发放下一个可用 Code。")) return action(() => api.issueCode(button.dataset.teamId), "已自动发放下一个可用 Code。", button);
    if (button.dataset.action === "open-team-from-workshop") { ui.tab = "grouping"; ui.groupingTab = "teams"; ui.teamConfigId = button.dataset.teamId; return renderStaff(root, state, api, controls); }
    if (button.dataset.action === "qualify" && window.confirm("已在 Game Portal 核验该队练习赛记录吗？")) return action(() => api.qualify(button.dataset.teamId), "该队已确认可参赛。", button);
    if (button.dataset.action === "workshop-note") { const note = window.prompt("内部备注（仅 Staff / Admin 可见，可留空）", button.dataset.currentNote || ""); if (note === null) return; return action(() => api.workshopNote(button.dataset.teamId, note), "Workshop 备注已保存。", button); }
  }, { signal: abort.signal });
  root.querySelector("#people-search")?.addEventListener("input", (event) => { ui.peopleQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector("#team-person-search")?.addEventListener("input", (event) => { ui.teamPeopleQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector("#team-picker-search")?.addEventListener("input", (event) => { ui.teamPickerQuery = event.target.value; renderStaff(root, state, api, controls); });
  root.querySelector("#admin-elevation")?.addEventListener("submit", async (event) => { event.preventDefault(); const pin = new FormData(event.target).get("adminPin"); try { await controls.adminLogin(pin); } catch (error) { notice.textContent = error.message; } });
  root.querySelectorAll(".staff-score-form").forEach((form) => form.addEventListener("submit", (event) => { event.preventDefault(); const data = new FormData(form); action(() => api.result(data.get("matchId"), data.get("scoreA"), data.get("scoreB")), "赛果已保存。", form.querySelector("button")); }));
}

function staffOverview(state) {
  const teams = activeTeams(state); const queues = { people: state.participants.filter((person) => !person.teamId).length, codes: teams.filter((team) => team.status === "ready_code").length, practice: teams.filter((team) => team.codeIssuedAt && team.qualificationStatus !== "ta_qualified").length, results: state.tournament ? [...state.tournament.matches, ...(state.tournament.knockoutMatches || [])].filter((match) => match.status === "ready").length : 0 };
  const next = queues.people ? ["grouping", "去安排队伍", "还有到场人员没有队伍。"] : queues.codes ? ["grouping", "去发放 Code", "已确认队伍正在等待领取资源。"] : queues.practice ? ["workshop", "去确认练习赛", "有队伍等待 TA 核验。"] : queues.results ? ["competition", "去录入赛果", "比赛正在进行，等待录入结果。"] : ["grouping", "查看现场人员", "当前没有待处理队列。"];
  return `<section class="metric-grid"><article><span>待组队</span><strong>${queues.people}</strong></article><article><span>待发 Code</span><strong>${queues.codes}</strong></article><article><span>待 TA 确认</span><strong>${queues.practice}</strong></article><article><span>待录赛果</span><strong>${queues.results}</strong></article></section><section class="card next-action"><h2>${e(next[1])}</h2><p>${e(next[2])}</p><button data-tab="${next[0]}">${e(next[1])}</button></section>`;
}

function staffWorkshop(state) {
  const teams = activeTeams(state); const ready = teams.filter((team) => team.status === "ready_code"); const pending = teams.filter((team) => team.codeIssuedAt && team.qualificationStatus !== "ta_qualified"); const qualified = teams.filter((team) => team.qualificationStatus === "ta_qualified");
  return `<section class="card"><h2>待发 Code · ${ready.length}</h2><div class="compact-list">${ready.map((team) => `<article><div><strong>${members(team)}</strong><small>队伍已确认</small></div><button data-action="open-team-from-workshop" data-team-id="${e(team.id)}">管理队伍</button></article>`).join("")}</div></section><section class="card"><h2>待 TA 确认 · ${pending.length}</h2><div class="staff-workshop-list">${pending.map((team) => `<article><div class="workshop-team-copy"><strong>${members(team)}</strong><small>${team.workshopNote ? `备注：${e(team.workshopNote)}` : "已发 Code，等待练习赛核验"}</small></div><div class="workshop-team-actions"><button data-action="workshop-note" data-team-id="${e(team.id)}" data-current-note="${e(team.workshopNote || "")}" class="note-button" aria-label="编辑 ${e(team.teamNumber)} 备注">备注</button><button data-action="qualify" data-team-id="${e(team.id)}" class="qualify-button">确认可参赛</button></div></article>`).join("")}</div></section><section class="card"><h2>已确认可参赛 · ${qualified.length}</h2><div class="compact-list">${qualified.map((team) => `<article><div><strong>${members(team)}</strong><small>${team.workshopNote ? `备注：${e(team.workshopNote)}` : "练习赛已核验"}</small></div><span class="pill">已确认</span></article>`).join("")}</div></section>`;
}

function staffCompetition(state) {
  const tournament = state.tournament; if (!tournament) return `<section class="empty-note">赛程未公布。</section>`;
  const groups = tournament.groups.map((group) => `<section class="card"><h2>${e(group.id)} 组积分榜</h2><table class="standings"><thead><tr><th>队伍</th><th>赛</th><th>胜</th><th>平</th><th>负</th><th>净胜球</th><th>分</th></tr></thead><tbody>${group.standings.map((row) => `<tr><td>${e(row.label)}</td><td>${row.played}</td><td>${row.won}</td><td>${row.drawn}</td><td>${row.lost}</td><td>${row.goalDifference}</td><td><strong>${row.points}</strong></td></tr>`).join("")}</tbody></table></section>`).join("");
  return `<section class="page-heading"><h1>${tournament.status === "knockout" ? "淘汰赛进行中" : "小组赛进行中"}</h1><div class="button-row"><a class="display-link" href="/display" target="_blank" rel="noreferrer">现场大屏</a></div></section>${groups}<section class="card"><h2>小组赛赛果</h2><div class="compact-list">${tournament.matches.map((match) => staffScoreForm(match, "小组赛")).join("")}</div></section>${tournament.knockoutMatches?.length ? `<section class="card"><h2>淘汰赛</h2><div class="compact-list">${tournament.knockoutMatches.map((match) => staffScoreForm(match, `第 ${match.round} 轮`)).join("")}</div></section>` : ""}`;
}

function staffScoreForm(match, caption) {
  if (match.status === "bye") return `<article><div><strong>${e(caption)} · ${e(match.teamALabel)} vs ${e(match.teamBLabel)}</strong><small>轮空晋级：${e(match.winnerLabel)}</small></div></article>`;
  if (!match.teamAId || !match.teamBId) return `<article><div><strong>${e(caption)}</strong><small>等待上一轮结果</small></div></article>`;
  return `<form class="staff-score-form"><input type="hidden" name="matchId" value="${e(match.id)}"><strong>${e(caption)} · ${e(match.teamALabel)} vs ${e(match.teamBLabel)}</strong><input name="scoreA" inputmode="numeric" value="${match.scoreA ?? ""}" placeholder="A"><span>:</span><input name="scoreB" inputmode="numeric" value="${match.scoreB ?? ""}" placeholder="B"><button>${match.status === "completed" ? "更正" : "保存"}</button></form>`;
}

function adminAccessModal() { return `<div class="modal-backdrop"><section class="dispatch-modal feedback-modal" role="dialog" aria-modal="true" aria-label="进入管理后台"><div class="modal-header"><div><h2>进入管理后台</h2></div><button type="button" data-action="close-admin-access" class="text-button">关闭</button></div><form id="admin-elevation" class="stack"><label>Admin PIN<input name="adminPin" type="password" required autofocus></label><button>进入管理后台</button></form></section></div>`; }
